import { safeParse } from 'valibot';
import { HISTORICAL_MAINTENANCE_ADOPTION_SCHEMA, type HistoricalMaintenanceAdoption } from './maintenance-adoption-schema.js';
import { createInitialMaintenanceCatalog, type InitialMaintenanceCatalog } from './maintenance.js';
import { INITIAL_PROFILE_REFERENCES, MAINTENANCE_RATE_REFERENCES, type InitialProfileId } from './defaults.js';
import { type Provenance } from './model.js';

/**
 * Cria um catálogo de manutenção adotando hipótese histórica.
 * 
 * Usa o catálogo inicial como base, seleciona taxas textuais pela categoria e perfil,
 * e produz novo catálogo com mesmas identidades/vínculos, proveniência condicional
 * com RCF §6.2 + perfil + reason bruto + rótulo de hipótese expressamente adotada.
 * 
 * @param scenarioId Identificador do cenário.
 * @param profileId Identificador do perfil inicial (optimistic/balanced/pessimistic).
 * @param adoption Declaração de adoção da hipótese histórica, validada por HISTORICAL_MAINTENANCE_ADOPTION_SCHEMA.
 * @returns Catálogo inicial com taxas ajustadas conforme hipótese adotada.
 * @throws Error se a adoção não for válida ou o perfil for inválido.
 */
export function createAdoptedMaintenanceCatalog(
  scenarioId: string,
  profileId: InitialProfileId,
  adoption: HistoricalMaintenanceAdoption
): InitialMaintenanceCatalog {
  // Validação obrigatória no runtime com safeParse e Error pt-BR
  const parseResult = safeParse(HISTORICAL_MAINTENANCE_ADOPTION_SCHEMA, adoption);
  if (!parseResult.success) {
    const errors = parseResult.error.map(e => e.message).join('; ');
    throw new Error(`Adoção de hipótese histórica inválida: ${errors}`);
  }

  // Validação explícita de perfil
  const validProfileIds = INITIAL_PROFILE_REFERENCES.map(p => p.id);
  if (!validProfileIds.includes(profileId)) {
    throw new Error(`Perfil inicial inválido: '${profileId}'. Valores válidos: ${validProfileIds.join(', ')}`);
  }

  // Obter catálogo inicial (preserva IDs brutos, parâmetros, itens, requisitos)
  const initialCatalog = createInitialMaintenanceCatalog(scenarioId, profileId);

  // Construir proveniência coerente: estimate/conditional, source com RCF+perfil+reason+rótulo, date/scope preservados
  const provenance: Provenance = {
    estimate: 'conditional',
    source: {
      type: 'rcf-reference',
      reference: 'RCF.md §6.2',
      context: {
        profileId,
        reason: adoption.reason,
        label: 'hipótese histórica expressamente adotada'
      }
    },
    date: null,
    competence: null,
    scope: scenarioId
  };

  // Mapear taxas textuais da tabela MAINTENANCE_RATE_REFERENCES pelo perfil
  const rateMap = new Map(
    MAINTENANCE_RATE_REFERENCES.map(ref => {
      const rate = ref.rates[profileId];
      return [ref.id, rate] as const;
    })
  );

  // Construir novos itens com taxas ajustadas, mantendo IDs, categorias, vínculos e proveniência
  const adjustedItems = initialCatalog.items.map(item => {
    if (item.nature !== 'rate') {
      return item;
    }

    const rateId = item.id;
    const rateValue = rateMap.get(rateId);
    if (rateValue == null) {
      return item;
    }

    return {
      ...item,
      amountParameterId: item.amountParameterId,
      provenance
    };
  });

  // Construir novos requisitos: applicable com costItemIds congelados, sem razão de pendência
  const adjustedRequirements = initialCatalog.requirements.map(req => {
    if (req.status !== 'applicable') {
      return req;
    }

    return {
      ...req,
      status: 'applicable' as const,
      costItemIds: Object.freeze([...req.costItemIds] as const),
      reason: adoption.reason
    };
  });

  return {
    parameters: Object.freeze([...initialCatalog.parameters]),
    items: Object.freeze(adjustedItems),
    requirements: Object.freeze(adjustedRequirements)
  };
}
